import * as React from "react";

import { useDropdownPill } from "./dropdown-pill";
import { cn } from "./utils";

export interface DropdownMenuContentProps extends React.HTMLAttributes<HTMLDivElement> {
  activeItem?: HTMLElement | null;
}

const DropdownMenuContent = React.forwardRef<
  HTMLDivElement,
  DropdownMenuContentProps
>(({ activeItem, className, onMouseLeave, ...props }, ref) => {
  const { handlers, pill } = useDropdownPill(onMouseLeave, activeItem);

  return (
    <div
      ref={ref}
      role="menu"
      className={cn(
        "ext-dropdown-content relative min-w-40 animate-[ext-pop-in_0.18s_cubic-bezier(0.22,1,0.36,1)_forwards] rounded-lg border border-border bg-popover p-1 text-popover-foreground shadow-[0_8px_24px_rgba(0,0,0,0.15)]",
        className
      )}
      {...handlers}
      {...props}
    >
      {pill}
      {props.children}
    </div>
  );
});
DropdownMenuContent.displayName = "DropdownMenuContent";

export { DropdownMenuContent };

import * as React from "react";

import { cn } from "./utils";

export interface DropdownMenuItemProps extends React.ButtonHTMLAttributes<HTMLButtonElement> {
  danger?: boolean;
}

const DropdownMenuItem = React.forwardRef<
  HTMLButtonElement,
  DropdownMenuItemProps
>(({ className, danger = false, type = "button", ...props }, ref) => (
  <button
    ref={ref}
    type={type}
    role="menuitem"
    data-dropdown-item
    className={cn(
      "ext-dropdown-item relative z-1 flex w-full cursor-pointer items-center gap-2 rounded-sm border-none bg-transparent px-2 py-1.5 text-left text-[0.8125rem] text-popover-foreground [transition:background-color_100ms_ease-out,color_100ms_ease-out,scale_100ms_ease-out] hover:text-foreground hover:outline-none focus-visible:text-foreground focus-visible:outline-none active:scale-98 disabled:pointer-events-none disabled:opacity-50 [&>svg]:size-4 [&>svg]:shrink-0",
      danger &&
        "ext-dropdown-item--danger text-destructive hover:bg-destructive/10 hover:text-destructive focus-visible:bg-destructive/10 focus-visible:text-destructive",
      className
    )}
    {...props}
  />
));
DropdownMenuItem.displayName = "DropdownMenuItem";

export { DropdownMenuItem };

import * as React from "react";
import { useCallback, useLayoutEffect, useState } from "react";

import { cn } from "./utils";

export interface DropdownPillHandlers {
  onFocus: (event: React.FocusEvent<HTMLDivElement>) => void;
  onMouseLeave: (event: React.MouseEvent<HTMLDivElement>) => void;
  onMouseOver: (event: React.MouseEvent<HTMLDivElement>) => void;
}

interface PillRect {
  height: number;
  left: number;
  top: number;
  width: number;
}

const measure = (item: HTMLElement): PillRect => ({
  height: item.offsetHeight,
  left: item.offsetLeft,
  top: item.offsetTop,
  width: item.offsetWidth,
});

const useDropdownPill = (
  onMouseLeave?: (event: React.MouseEvent<HTMLDivElement>) => void,
  activeItem?: HTMLElement | null
): { handlers: DropdownPillHandlers; pill: React.ReactNode } => {
  const [rect, setRect] = useState<PillRect | null>(null);

  useLayoutEffect(() => {
    if (activeItem) {
      setRect(measure(activeItem));
    }
  }, [activeItem]);

  const handleItemEnter = useCallback((target: EventTarget | null) => {
    const item = (target as HTMLElement).closest<HTMLElement>(
      "[data-dropdown-item]"
    );
    if (!item) {
      return;
    }
    setRect(measure(item));
  }, []);

  const handlers: DropdownPillHandlers = {
    onFocus: (event: React.FocusEvent<HTMLDivElement>) => {
      handleItemEnter(event.target);
    },
    onMouseLeave: (event: React.MouseEvent<HTMLDivElement>) => {
      setRect(activeItem ? measure(activeItem) : null);
      onMouseLeave?.(event);
    },
    onMouseOver: (event: React.MouseEvent<HTMLDivElement>) => {
      handleItemEnter(event.target);
    },
  };

  const pill = (
    <div
      aria-hidden="true"
      className={cn(
        "ext-dropdown-pill pointer-events-none absolute top-0 left-0 z-0 rounded-sm bg-primary/6 opacity-0 [transition:top_220ms_cubic-bezier(0.22,1,0.36,1),left_220ms_cubic-bezier(0.22,1,0.36,1),width_220ms_cubic-bezier(0.22,1,0.36,1),height_220ms_cubic-bezier(0.22,1,0.36,1),opacity_150ms_ease-out]",
        rect && "ext-dropdown-pill--visible opacity-100"
      )}
      style={
        rect
          ? {
              height: rect.height,
              left: rect.left,
              top: rect.top,
              width: rect.width,
            }
          : undefined
      }
    />
  );

  return { handlers, pill };
};

export { useDropdownPill };

